export class SessionTimeout {
    private static startTime: number;
    private static timeout: number;
    private static timerId: number;
    private static sessionTimeoutCallback: () => void;

    public static start(timeout: number, sessionTimeoutCallback: () => void) {
        this.startTime = Date.now();
        this.timeout = timeout;
        this.sessionTimeoutCallback = sessionTimeoutCallback;
        document.addEventListener('click', () => this.reset());
        this.reset();
    }

    private static reset() {
        window.clearTimeout(this.timerId);
        this.timerId = window.setTimeout(() => this.sessionTimeoutCallback(), this.timeout);
    }

    public static get totalTime() {
        return Date.now() - this.startTime;
    }
}